#define ONYX_BACKGROUND_CLIP_MASK 0x700
#define ONYX_BACKGROUND_REPEAT_INDEX 12
#define ONYX_BACKGROUND_REPEAT_MASK 0x3800
#define ONYX_BACKGROUND_POSITION_INDEX 3
#define ONYX_BACKGROUND_POSITION_MASK 0xffe00000
#define ONYX_BACKGROUND_SIZE_INDEX 9
#define ONYX_BACKGROUND_SIZE_MASK 0x7ffc
#define ONYX_BORDER_TOP_COLOR_INDEX 18
#define ONYX_BORDER_TOP_COLOR_MASK 0x30000000
#define ONYX_BORDER_RIGHT_COLOR_INDEX 18
#define ONYX_BORDER_RIGHT_COLOR_MASK 0xc000000
#define ONYX_BORDER_BOTTOM_COLOR_INDEX 18
#define ONYX_BORDER_BOTTOM_COLOR_MASK 0x300000
