#define ONYX_BORDER_BOTTOM_RIGHT_RADIUS_INDEX 10
#define ONYX_BORDER_BOTTOM_RIGHT_RADIUS_MASK 0x3f00
#define ONYX_BOX_SHADOW_INDEX 0
